const fs = require('node:fs');
const path = require('node:path');
const read = name => JSON.parse(fs.readFileSync(path.join(__dirname,name+'-arsenal.json'),'utf8'));
const data = {chassis:['warden','kestrel','basilisk'].map(read),weapons:read('weapons')};
fs.writeFileSync(path.join(__dirname,'../dist/arsenal-visuals.js'),
  '// Generated by tools/render_arsenal.py and tools/assemble_arsenal.cjs.\nwindow.IRON_VOW_ARSENAL = '+JSON.stringify(data)+';\n');
